  const GEN_FACTOR = 0.8 * 0.87 * 0.9;

  /**
   * Sites confirmed safe by field engineering assessment despite the engine
   * flagging them (e.g. battery backup marginally under 1 h threshold).
   * Add/remove cowIds here to override the computed risk classification.
   */
  const SAFE_OVERRIDES = new Set([
    "CWN002", // Mina SB — battery 0.95 h, confirmed safe
    "CWN074", // Muzdalifah SB — battery 0.833 h, confirmed safe
  ]);

  export const ALL_SITES: SiteConfig[] = realSiteData.map((s) => {
    const isSG = s.powerSource === "SG";
    const isDG = s.powerSource === "DG";
    const isOutdoor = s.shelterType.toLowerCase() === "outdoor";
    const primeNetKw  = (isSG || isDG) ? s.primeGenNetPowerKw : s.primeSecNetPowerKw;
    const backupNetKw = s.backupGenNetPowerKw;
    const mc = MC_LOOKUP[s.cowId];
    return {
      id:        s.cowId,
      name:      s.cowId,
      location:  s.location,
      lat:       mc?.lat ?? s.latitude,
      lng:       mc?.lng ?? s.longitude,
      siteType:  isOutdoor ? "outdoor_cabinet" : "shelter",
      // DG treated same as SB: Gen1 = prime source, Gen2 = backup source
      powerConfig: isSG ? "single_generator" : "commercial_with_backup",
      generatorKva:      primeNetKw  / GEN_FACTOR,
      generatorAge:      0,
      secCapacityAmp:    s.secMeterCapacityAmp,
      backupGeneratorKva:  isSG ? undefined : backupNetKw / GEN_FACTOR,
      backupGeneratorAge:  isSG ? undefined : 0,
      telecomPowerKw:      s.telecomLoadTotalKw || s.telecomLoadAllKw,
      telecomHeatKBtuH:    s.telecomHeatDissipationKbtuh / 1000,
      ac1CapacityBtu:  s.ac1CapacityBtu,
      ac1Age:          s.ac1AgeYears,
      ac2CapacityBtu:  s.ac2CapacityBtu > 0 ? s.ac2CapacityBtu : undefined,
      ac2Age:          s.ac2CapacityBtu > 0 ? s.ac2AgeYears    : undefined,
      batteryCapacityAh: s.batteriesCapacityAh * s.numStrings,
      batteryType:       "lead_acid",
      batteryAge:        s.batteriesAgeYears,
      batteryMaxUsefulTimeHours: s.batteriesMaxUsefulTimeHours,
      rectifierCapacityKw: s.rectifierCapacityKw,
      connectedTechnology: s.connectedTechnology,
      rawGenKva:       (isSG || isDG) ? s.singleGenCapacityKva : undefined,
      rawBackupGenKva: !isSG ? s.backupGenCapacityKva || undefined : undefined,
      primeGenNetPowerKw:  isDG ? s.primeGenNetPowerKw  : undefined,
      backupGenNetPowerKw: isDG ? s.backupGenNetPowerKw : undefined,
      // Team Cluster / Hajj MC
      escalationTeam: mc?.escalationTeam,
      hajjMC:         mc?.hajjMC,
      mcLat:          mc?.mcLat,
      mcLng:          mc?.mcLng,
      // Engineering safe override — suppresses computed risk classification
      ...(SAFE_OVERRIDES.has(s.cowId) ? { placeholderSafe: true } : {}),
    };
  });